-- Keep read access separate from mutations so SELECT does not evaluate duplicate permissive policies.

-- AI insights
drop policy if exists santiye_ai_insights_write on public.santiye_ai_insights;
create policy santiye_ai_insights_insert on public.santiye_ai_insights for insert to authenticated with check (exists (select 1 from public.santiye_projects p where p.id=santiye_ai_insights.project_id and public.santiye_has_company_role(p.company_id,array['owner','project_manager'])));
create policy santiye_ai_insights_update on public.santiye_ai_insights for update to authenticated using (exists (select 1 from public.santiye_projects p where p.id=santiye_ai_insights.project_id and public.santiye_has_company_role(p.company_id,array['owner','project_manager']))) with check (exists (select 1 from public.santiye_projects p where p.id=santiye_ai_insights.project_id and public.santiye_has_company_role(p.company_id,array['owner','project_manager'])));
create policy santiye_ai_insights_delete on public.santiye_ai_insights for delete to authenticated using (exists (select 1 from public.santiye_projects p where p.id=santiye_ai_insights.project_id and public.santiye_has_company_role(p.company_id,array['owner','project_manager'])));

