-- Purchase order items
drop policy if exists santiye_purchase_order_items_write on public.santiye_purchase_order_items;
create policy santiye_purchase_order_items_insert on public.santiye_purchase_order_items for insert to authenticated with check (exists (select 1 from public.santiye_purchase_orders o join public.santiye_projects p on p.id=o.project_id where o.id=santiye_purchase_order_items.purchase_order_id and public.santiye_has_company_role(p.company_id,array['owner','project_manager','purchasing'])));
create policy santiye_purchase_order_items_update on public.santiye_purchase_order_items for update to authenticated using (exists (select 1 from public.santiye_purchase_orders o join public.santiye_projects p on p.id=o.project_id where o.id=santiye_purchase_order_items.purchase_order_id and public.santiye_has_company_role(p.company_id,array['owner','project_manager','purchasing']))) with check (exists (select 1 from public.santiye_purchase_orders o join public.santiye_projects p on p.id=o.project_id where o.id=santiye_purchase_order_items.purchase_order_id and public.santiye_has_company_role(p.company_id,array['owner','project_manager','purchasing'])));
create policy santiye_purchase_order_items_delete on public.santiye_purchase_order_items for delete to authenticated using (exists (select 1 from public.santiye_purchase_orders o join public.santiye_projects p on p.id=o.project_id where o.id=santiye_purchase_order_items.purchase_order_id and public.santiye_has_company_role(p.company_id,array['owner','project_manager','purchasing'])));
